export const direitoConstitucionalQuestions: Question[] = [
  {"id": "direito-constitucional-conc-v1-mc-i-01", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Princípios fundamentais", "subtopic": "Fundamentos da República", "difficulty": "iniciante", "type": "multiple-choice", "statement": "De acordo com o art. 1º da Constituição Federal, é um dos fundamentos da República Federativa do Brasil", "alternatives": [{"id": "A", "text": "a dignidade da pessoa humana"}, {"id": "B", "text": "garantir o desenvolvimento nacional"}, {"id": "C", "text": "erradicar a pobreza e a marginalização"}, {"id": "D", "text": "a independência nacional"}, {"id": "E", "text": "a defesa do consumidor"}], "correctAnswer": "A", "explanation": "O art. 1º lista cinco fundamentos: soberania, cidadania, dignidade da pessoa humana, valores sociais do trabalho e da livre iniciativa e pluralismo político. Os objetivos estão no art. 3º, e os princípios das relações internacionais, no art. 4º.", "alternativeExplanations": {"A": "Correto. A dignidade da pessoa humana está entre os fundamentos do art. 1º.", "B": "Garantir o desenvolvimento nacional é um objetivo fundamental (art. 3º), não um fundamento.", "C": "Erradicar a pobreza é um objetivo fundamental (art. 3º).", "D": "A independência nacional é princípio das relações internacionais (art. 4º).", "E": "A defesa do consumidor é princípio da ordem econômica (art. 170)."}, "tags": ["principios-fundamentais", "fundamentos", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["principios-fundamentais", "fundamentos"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-i-02", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Princípios fundamentais", "subtopic": "Separação dos Poderes", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Segundo o art. 2º da Constituição, são Poderes da União", "alternatives": [{"id": "A", "text": "o Legislativo, o Executivo, o Judiciário e o Ministério Público"}, {"id": "B", "text": "o Legislativo, o Executivo e o Judiciário, independentes e harmônicos entre si"}, {"id": "C", "text": "o Executivo, o Legislativo e o Moderador"}, {"id": "D", "text": "a União, os Estados e os Municípios"}, {"id": "E", "text": "o Federal, o Estadual e o Municipal"}], "correctAnswer": "B", "explanation": "O art. 2º estabelece que são Poderes da União, independentes e harmônicos entre si, o Legislativo, o Executivo e o Judiciário. A separação dos Poderes também é cláusula pétrea.", "alternativeExplanations": {"A": "O Ministério Público é função essencial à Justiça, não um quarto Poder.", "B": "Correto. É a redação do art. 2º.", "C": "O Poder Moderador existia na Constituição de 1824, não na atual.", "D": "União, Estados e Municípios são entes federativos, não Poderes.", "E": "Essas são esferas da Federação, não os Poderes da União."}, "tags": ["separacao-dos-poderes", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["separacao-dos-poderes"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-i-03", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Remédios constitucionais", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Uma pessoa foi presa ilegalmente, sem flagrante e sem ordem judicial. O remédio constitucional adequado para proteger sua liberdade de locomoção é o", "alternatives": [{"id": "A", "text": "habeas data"}, {"id": "B", "text": "mandado de injunção"}, {"id": "C", "text": "habeas corpus"}, {"id": "D", "text": "ação popular"}, {"id": "E", "text": "mandado de segurança"}], "correctAnswer": "C", "explanation": "Pelo art. 5º, LXVIII, concede-se habeas corpus sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder.", "alternativeExplanations": {"A": "O habeas data serve para conhecer ou retificar informações pessoais em bancos de dados públicos.", "B": "O mandado de injunção supre a falta de norma regulamentadora.", "C": "Correto. O habeas corpus protege a liberdade de locomoção contra ilegalidade ou abuso de poder.", "D": "A ação popular busca anular ato lesivo ao patrimônio público, à moralidade ou ao meio ambiente.", "E": "O mandado de segurança protege direito líquido e certo que não seja amparado por habeas corpus ou habeas data."}, "tags": ["remedios-constitucionais", "habeas-corpus", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["remedios-constitucionais", "habeas-corpus"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-i-04", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos sociais", "subtopic": "Rol do art. 6º", "difficulty": "iniciante", "type": "multiple-choice", "statement": "NÃO está entre os direitos sociais listados no art. 6º da Constituição", "alternatives": [{"id": "A", "text": "a educação"}, {"id": "B", "text": "a moradia"}, {"id": "C", "text": "o transporte"}, {"id": "D", "text": "o direito de propriedade"}, {"id": "E", "text": "o lazer"}], "correctAnswer": "D", "explanation": "O art. 6º lista como direitos sociais a educação, a saúde, a alimentação, o trabalho, a moradia, o transporte, o lazer, a segurança, a previdência social, a proteção à maternidade e à infância e a assistência aos desamparados. A propriedade é garantida no art. 5º.", "alternativeExplanations": {"A": "A educação é o primeiro direito social do art. 6º.", "B": "A moradia está no rol do art. 6º.", "C": "O transporte foi incluído no art. 6º pela Emenda Constitucional 90/2015.", "D": "Correto. A propriedade é garantida no art. 5º, entre os direitos individuais, e não no art. 6º.", "E": "O lazer está no rol do art. 6º."}, "tags": ["direitos-sociais", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-sociais"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-i-05", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos políticos", "subtopic": "Alistamento e voto", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Pela Constituição, o alistamento eleitoral e o voto são facultativos para", "alternatives": [{"id": "A", "text": "todos os maiores de 18 anos"}, {"id": "B", "text": "os maiores de 60 anos"}, {"id": "C", "text": "os servidores públicos em exercício"}, {"id": "D", "text": "os conscritos, durante o serviço militar obrigatório"}, {"id": "E", "text": "os analfabetos, os maiores de 70 anos e os maiores de 16 e menores de 18 anos"}], "correctAnswer": "E", "explanation": "O art. 14, § 1º, torna o alistamento e o voto obrigatórios para os maiores de 18 anos e facultativos para analfabetos, maiores de 70 anos e maiores de 16 e menores de 18 anos. Estrangeiros e conscritos não podem se alistar.", "alternativeExplanations": {"A": "Para os maiores de 18 anos, o voto é obrigatório, com as exceções previstas.", "B": "O voto passa a ser facultativo aos 70 anos, não aos 60.", "C": "Servidores públicos não têm voto facultativo por essa condição.", "D": "Os conscritos, nesse período, não podem se alistar como eleitores.", "E": "Correto. Esses são os três casos de voto facultativo do art. 14."}, "tags": ["direitos-politicos", "voto", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-politicos", "voto"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-i-06", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Organização do Estado", "subtopic": "Federação", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Segundo o art. 18 da Constituição, a organização político-administrativa da República Federativa do Brasil compreende", "alternatives": [{"id": "A", "text": "a União, os Estados, o Distrito Federal e os Municípios, todos autônomos"}, {"id": "B", "text": "a União e os Estados, ficando os Municípios subordinados aos Estados"}, {"id": "C", "text": "a União, os Estados e os Territórios Federais, como entes autônomos"}, {"id": "D", "text": "apenas a União, que delega competências aos demais"}, {"id": "E", "text": "a União, os Estados e o Distrito Federal, sem os Municípios"}], "correctAnswer": "A", "explanation": "O art. 18 afirma que a organização político-administrativa compreende a União, os Estados, o Distrito Federal e os Municípios, todos autônomos. Os Territórios Federais, se criados, integram a União.", "alternativeExplanations": {"A": "Correto. É a redação do art. 18.", "B": "Os Municípios são entes autônomos, não subordinados aos Estados.", "C": "Os Territórios Federais integram a União e não são entes autônomos.", "D": "A Federação é formada por entes autônomos, com competências próprias.", "E": "Os Municípios também são entes da Federação."}, "tags": ["organizacao-do-estado", "federacao", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["organizacao-do-estado", "federacao"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-i-07", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Nacionalidade", "subtopic": "Cargos privativos de brasileiro nato", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Entre os cargos a seguir, é privativo de brasileiro nato o de", "alternatives": [{"id": "A", "text": "Deputado Federal"}, {"id": "B", "text": "Ministro do Supremo Tribunal Federal"}, {"id": "C", "text": "Senador"}, {"id": "D", "text": "Ministro do Superior Tribunal de Justiça"}, {"id": "E", "text": "Governador de Estado"}], "correctAnswer": "B", "explanation": "O art. 12, § 3º, reserva a brasileiros natos os cargos de Presidente e Vice-Presidente da República, Presidente da Câmara, Presidente do Senado, Ministro do STF, carreira diplomática, oficial das Forças Armadas e Ministro de Estado da Defesa.", "alternativeExplanations": {"A": "Só o Presidente da Câmara precisa ser nato; o cargo de Deputado não.", "B": "Correto. O cargo de Ministro do STF está no rol do art. 12, § 3º.", "C": "Só o Presidente do Senado precisa ser nato; o cargo de Senador não.", "D": "Ministros do STJ não estão no rol de cargos privativos de nato.", "E": "O cargo de Governador não é privativo de brasileiro nato."}, "tags": ["nacionalidade", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["nacionalidade"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-m-01", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Inviolabilidade do domicílio", "difficulty": "medio", "type": "multiple-choice", "statement": "Segundo o art. 5º, XI, da Constituição, sem o consentimento do morador, é permitido entrar na casa", "alternatives": [{"id": "A", "text": "a qualquer hora, por determinação judicial"}, {"id": "B", "text": "somente por determinação judicial, durante o dia"}, {"id": "C", "text": "a qualquer hora, em caso de flagrante delito, desastre ou para prestar socorro, e, durante o dia, por determinação judicial"}, {"id": "D", "text": "por ordem de autoridade policial, durante a noite"}, {"id": "E", "text": "apenas em caso de flagrante delito"}], "correctAnswer": "C", "explanation": "A casa é asilo inviolável. Sem consentimento, só se pode entrar em caso de flagrante delito ou desastre, para prestar socorro, ou, durante o dia, por determinação judicial.", "alternativeExplanations": {"A": "A ordem judicial só autoriza a entrada durante o dia.", "B": "Também é permitida a entrada em flagrante delito, desastre ou para prestar socorro.", "C": "Correto. É exatamente o que prevê o inciso XI.", "D": "A Constituição não autoriza entrada por simples ordem policial.", "E": "Há outras hipóteses: desastre, socorro e ordem judicial durante o dia."}, "tags": ["direitos-individuais", "domicilio", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-individuais", "domicilio"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-m-02", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Crimes inafiançáveis", "difficulty": "medio", "type": "multiple-choice", "statement": "A Constituição determina que são crimes inafiançáveis e imprescritíveis", "alternatives": [{"id": "A", "text": "a tortura e o tráfico de drogas"}, {"id": "B", "text": "o terrorismo e os crimes hediondos"}, {"id": "C", "text": "o racismo e a tortura"}, {"id": "D", "text": "o racismo e a ação de grupos armados contra a ordem constitucional e o Estado Democrático"}, {"id": "E", "text": "o homicídio e o latrocínio"}], "correctAnswer": "D", "explanation": "A Constituição prevê apenas dois crimes imprescritíveis: o racismo (art. 5º, XLII) e a ação de grupos armados contra a ordem constitucional e o Estado Democrático (XLIV). Tortura, tráfico, terrorismo e hediondos são inafiançáveis e insuscetíveis de graça ou anistia (XLIII).", "alternativeExplanations": {"A": "Tortura e tráfico são inafiançáveis e insuscetíveis de graça ou anistia, mas não imprescritíveis.", "B": "Terrorismo e hediondos são inafiançáveis, mas não imprescritíveis.", "C": "A tortura não é imprescritível pela Constituição.", "D": "Correto. São os dois casos dos incisos XLII e XLIV do art. 5º.", "E": "A Constituição não trata esses crimes como imprescritíveis."}, "tags": ["direitos-individuais", "crimes-constitucionais", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-individuais", "crimes-constitucionais"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-m-03", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Habeas data", "difficulty": "medio", "type": "multiple-choice", "statement": "Um cidadão quer conhecer as informações sobre ele que constam em um banco de dados de um órgão público, que se recusou a fornecê-las. O instrumento constitucional adequado é o", "alternatives": [{"id": "A", "text": "habeas corpus"}, {"id": "B", "text": "mandado de injunção"}, {"id": "C", "text": "ação popular"}, {"id": "D", "text": "mandado de segurança coletivo"}, {"id": "E", "text": "habeas data"}], "correctAnswer": "E", "explanation": "O habeas data (art. 5º, LXXII) assegura o conhecimento de informações relativas à pessoa do impetrante, constantes de registros ou bancos de dados de entidades governamentais ou de caráter público, e a retificação desses dados.", "alternativeExplanations": {"A": "O habeas corpus protege a liberdade de locomoção.", "B": "O mandado de injunção supre a falta de norma regulamentadora.", "C": "A ação popular protege o patrimônio público e a moralidade, não dados pessoais.", "D": "O mandado de segurança é subsidiário: não cabe quando o caso é de habeas data.", "E": "Correto. O habeas data assegura o conhecimento e a retificação de informações relativas ao próprio impetrante."}, "tags": ["remedios-constitucionais", "habeas-data", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["remedios-constitucionais", "habeas-data"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-m-04", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Ação popular", "difficulty": "medio", "type": "multiple-choice", "statement": "Tem legitimidade para propor ação popular que vise a anular ato lesivo ao patrimônio público ou à moralidade administrativa", "alternatives": [{"id": "A", "text": "qualquer cidadão"}, {"id": "B", "text": "apenas o Ministério Público"}, {"id": "C", "text": "somente partidos políticos com representação no Congresso"}, {"id": "D", "text": "qualquer pessoa jurídica"}, {"id": "E", "text": "apenas a Defensoria Pública"}], "correctAnswer": "A", "explanation": "Qualquer cidadão pode propor ação popular para anular ato lesivo ao patrimônio público, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural. Salvo má-fé comprovada, o autor fica isento de custas e do ônus da sucumbência.", "alternativeExplanations": {"A": "Correto. O art. 5º, LXXIII, dá legitimidade a qualquer cidadão, entendido como quem está no gozo dos direitos políticos.", "B": "O Ministério Público tem outras ações, como a ação civil pública; a ação popular é do cidadão.", "C": "Partidos têm legitimidade para outras ações, como o mandado de segurança coletivo.", "D": "Pessoa jurídica não pode propor ação popular (Súmula 365 do STF).", "E": "A Defensoria não é a legitimada para a ação popular."}, "tags": ["remedios-constitucionais", "acao-popular", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["remedios-constitucionais", "acao-popular"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-m-05", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos políticos", "subtopic": "Condições de elegibilidade", "difficulty": "medio", "type": "multiple-choice", "statement": "A idade mínima de 35 anos é condição de elegibilidade para", "alternatives": [{"id": "A", "text": "Governador e Vice-Governador"}, {"id": "B", "text": "Presidente e Vice-Presidente da República e Senador"}, {"id": "C", "text": "Deputado Federal"}, {"id": "D", "text": "Prefeito"}, {"id": "E", "text": "Vereador"}], "correctAnswer": "B", "explanation": "Idades mínimas: 35 anos para Presidente, Vice e Senador; 30 para Governador e Vice; 21 para Deputado, Prefeito, Vice-Prefeito e juiz de paz; 18 para Vereador.", "alternativeExplanations": {"A": "Para Governador e Vice, a idade mínima é de 30 anos.", "B": "Correto. É o que prevê o art. 14, § 3º, VI, a.", "C": "Para Deputado Federal, a idade mínima é de 21 anos.", "D": "Para Prefeito e Vice, a idade mínima é de 21 anos.", "E": "Para Vereador, a idade mínima é de 18 anos."}, "tags": ["direitos-politicos", "elegibilidade", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-politicos", "elegibilidade"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-m-06", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Administração pública", "subtopic": "Acumulação de cargos", "difficulty": "medio", "type": "multiple-choice", "statement": "Havendo compatibilidade de horários, a Constituição permite a acumulação remunerada de", "alternatives": [{"id": "A", "text": "dois cargos técnicos quaisquer"}, {"id": "B", "text": "qualquer cargos, desde que a soma não passe de 44 horas semanais"}, {"id": "C", "text": "dois cargos de professor"}, {"id": "D", "text": "dois cargos efetivos de nível médio no mesmo órgão"}, {"id": "E", "text": "um cargo administrativo e um cargo em comissão em outro ente"}], "correctAnswer": "C", "explanation": "A regra é a vedação de acumular cargos públicos. As exceções do art. 37, XVI, com compatibilidade de horários, são: dois cargos de professor; um de professor com outro técnico ou científico; e dois de profissionais de saúde com profissões regulamentadas.", "alternativeExplanations": {"A": "A Constituição permite um de professor com outro técnico ou científico, não dois técnicos.", "B": "A regra é a proibição; só há as exceções listadas na Constituição.", "C": "Correto. É uma das hipóteses do art. 37, XVI.", "D": "Não há essa exceção na Constituição.", "E": "Essa combinação não está entre as exceções."}, "tags": ["administracao-publica", "acumulacao", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["administracao-publica", "acumulacao"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-m-07", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Administração pública", "subtopic": "Concurso público", "difficulty": "medio", "type": "multiple-choice", "statement": "Pela Constituição, o prazo de validade do concurso público é de", "alternatives": [{"id": "A", "text": "até quatro anos, sem prorrogação"}, {"id": "B", "text": "dois anos, prorrogável indefinidamente"}, {"id": "C", "text": "um ano, prorrogável duas vezes"}, {"id": "D", "text": "até dois anos, prorrogável uma vez, por igual período"}, {"id": "E", "text": "até cinco anos, a critério da Administração"}], "correctAnswer": "D", "explanation": "O art. 37, III, fixa a validade do concurso em até dois anos, prorrogável uma vez por igual período. O edital define o prazo dentro desse limite.", "alternativeExplanations": {"A": "O prazo máximo inicial é de dois anos.", "B": "A prorrogação só pode ocorrer uma vez.", "C": "A Constituição prevê uma única prorrogação.", "D": "Correto. É a regra do art. 37, III.", "E": "O limite é de dois anos, prorrogável uma vez."}, "tags": ["administracao-publica", "concurso-publico", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["administracao-publica", "concurso-publico"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-a-01", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Processo legislativo", "subtopic": "Cláusulas pétreas", "difficulty": "avancado", "type": "multiple-choice", "statement": "NÃO está prevista expressamente como cláusula pétrea no art. 60, § 4º, da Constituição", "alternatives": [{"id": "A", "text": "a forma federativa de Estado"}, {"id": "B", "text": "o voto direto, secreto, universal e periódico"}, {"id": "C", "text": "a separação dos Poderes"}, {"id": "D", "text": "os direitos e garantias individuais"}, {"id": "E", "text": "a forma republicana de governo"}], "correctAnswer": "E", "explanation": "O art. 60, § 4º, proíbe propostas de emenda tendentes a abolir a forma federativa de Estado, o voto direto, secreto, universal e periódico, a separação dos Poderes e os direitos e garantias individuais. A forma republicana não consta do rol.", "alternativeExplanations": {"A": "A forma federativa é cláusula pétrea expressa.", "B": "O voto direto, secreto, universal e periódico é cláusula pétrea expressa.", "C": "A separação dos Poderes é cláusula pétrea expressa.", "D": "Os direitos e garantias individuais são cláusula pétrea expressa.", "E": "Correto. A república não está no rol do art. 60, § 4º; ela foi inclusive objeto do plebiscito de 1993."}, "tags": ["clausulas-petreas", "processo-legislativo", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["clausulas-petreas", "processo-legislativo"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-a-02", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Processo legislativo", "subtopic": "Emenda constitucional", "difficulty": "avancado", "type": "multiple-choice", "statement": "Uma proposta de emenda à Constituição é aprovada quando obtém", "alternatives": [{"id": "A", "text": "três quintos dos votos dos membros de cada Casa do Congresso, em dois turnos de votação"}, {"id": "B", "text": "maioria absoluta, em turno único, em sessão conjunta"}, {"id": "C", "text": "dois terços dos votos em sessão conjunta do Congresso"}, {"id": "D", "text": "maioria simples, seguida de sanção presidencial"}, {"id": "E", "text": "três quintos dos votos, em turno único, apenas no Senado"}], "correctAnswer": "A", "explanation": "A PEC é discutida e votada em cada Casa do Congresso, em dois turnos, e aprovada se obtiver, em ambos, três quintos dos votos dos respectivos membros. Depois é promulgada pelas Mesas da Câmara e do Senado, sem sanção presidencial.", "alternativeExplanations": {"A": "Correto. É o quórum do art. 60, § 2º.", "B": "A PEC é votada em cada Casa separadamente, em dois turnos.", "C": "O quórum é de três quintos, em cada Casa.", "D": "Emenda constitucional não vai à sanção; é promulgada pelas Mesas da Câmara e do Senado.", "E": "A votação ocorre nas duas Casas, em dois turnos cada."}, "tags": ["emenda-constitucional", "processo-legislativo", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["emenda-constitucional", "processo-legislativo"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-a-03", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Administração pública", "subtopic": "Estabilidade", "difficulty": "avancado", "type": "multiple-choice", "statement": "Entre as hipóteses de perda do cargo pelo servidor estável previstas no art. 41 da Constituição, estão", "alternatives": [{"id": "A", "text": "apenas a sentença judicial transitada em julgado"}, {"id": "B", "text": "a sentença judicial transitada em julgado, o processo administrativo com ampla defesa e a avaliação periódica de desempenho, assegurada ampla defesa"}, {"id": "C", "text": "a decisão discricionária do chefe do Poder"}, {"id": "D", "text": "a simples mudança de governo"}, {"id": "E", "text": "somente a aposentadoria compulsória"}], "correctAnswer": "B", "explanation": "O servidor nomeado em virtude de concurso fica estável após três anos de efetivo exercício. Pelo art. 41, § 1º, só perde o cargo por sentença judicial transitada em julgado, processo administrativo com ampla defesa ou avaliação periódica de desempenho, assegurada ampla defesa. O art. 169 prevê ainda a exoneração por excesso de despesa com pessoal.", "alternativeExplanations": {"A": "Há também o processo administrativo e a avaliação periódica de desempenho.", "B": "Correto. São as três hipóteses do art. 41, § 1º.", "C": "O servidor estável não pode ser dispensado por decisão discricionária.", "D": "A mudança de governo não é causa de perda do cargo.", "E": "A aposentadoria não é hipótese de perda do cargo por penalidade."}, "tags": ["administracao-publica", "estabilidade", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["administracao-publica", "estabilidade"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-a-04", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Mandado de injunção", "difficulty": "avancado", "type": "multiple-choice", "statement": "Servidores públicos não conseguem exercer um direito previsto na Constituição porque a lei que deveria regulamentá-lo nunca foi editada. O instrumento adequado para enfrentar essa omissão, no caso concreto, é o", "alternatives": [{"id": "A", "text": "mandado de segurança"}, {"id": "B", "text": "habeas data"}, {"id": "C", "text": "mandado de injunção"}, {"id": "D", "text": "ação popular"}, {"id": "E", "text": "habeas corpus"}], "correctAnswer": "C", "explanation": "Pelo art. 5º, LXXI, concede-se mandado de injunção sempre que a falta de norma regulamentadora torne inviável o exercício dos direitos e liberdades constitucionais. Um exemplo clássico são os julgamentos do STF sobre o direito de greve dos servidores.", "alternativeExplanations": {"A": "O mandado de segurança protege direito líquido e certo contra ato ilegal, não supre omissão normativa.", "B": "O habeas data trata de informações pessoais.", "C": "Correto. O mandado de injunção cabe quando a falta de norma regulamentadora torna inviável o exercício de direitos constitucionais.", "D": "A ação popular busca anular atos lesivos ao patrimônio público.", "E": "O habeas corpus protege a liberdade de locomoção."}, "tags": ["remedios-constitucionais", "mandado-de-injuncao", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["remedios-constitucionais", "mandado-de-injuncao"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-a-05", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Organização do Estado", "subtopic": "Competências legislativas", "difficulty": "avancado", "type": "multiple-choice", "statement": "Compete privativamente à União legislar sobre", "alternatives": [{"id": "A", "text": "direito tributário e financeiro"}, {"id": "B", "text": "educação e cultura"}, {"id": "C", "text": "proteção do meio ambiente"}, {"id": "D", "text": "direito penal e direito do trabalho"}, {"id": "E", "text": "assuntos de interesse local"}], "correctAnswer": "D", "explanation": "O art. 22, I, reserva à União legislar sobre direito civil, comercial, penal, processual, eleitoral, agrário, marítimo, aeronáutico, espacial e do trabalho. O art. 24 traz as matérias concorrentes, e o art. 30, as de interesse local dos Municípios.", "alternativeExplanations": {"A": "Direito tributário e financeiro são de competência concorrente (art. 24).", "B": "Educação e cultura são de competência concorrente (art. 24).", "C": "A proteção do meio ambiente é competência legislativa concorrente (art. 24).", "D": "Correto. Ambos estão no art. 22, I, entre as competências privativas da União.", "E": "Assuntos de interesse local são de competência dos Municípios (art. 30)."}, "tags": ["organizacao-do-estado", "competencias", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["organizacao-do-estado", "competencias"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-mc-a-06", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Processo legislativo", "subtopic": "Medidas provisórias", "difficulty": "avancado", "type": "multiple-choice", "statement": "Uma medida provisória perde a eficácia, desde a edição, se não for convertida em lei no prazo de", "alternatives": [{"id": "A", "text": "30 dias, improrrogável"}, {"id": "B", "text": "90 dias, contados da publicação"}, {"id": "C", "text": "120 dias, prorrogável por mais 120"}, {"id": "D", "text": "180 dias, a critério do Congresso"}, {"id": "E", "text": "60 dias, prorrogável uma vez por igual período"}], "correctAnswer": "E", "explanation": "A medida provisória vale por 60 dias, prorrogáveis uma vez por igual período. O prazo fica suspenso durante o recesso do Congresso. Se não for convertida em lei, perde a eficácia desde a edição.", "alternativeExplanations": {"A": "O prazo é de 60 dias, e há uma prorrogação.", "B": "A Constituição não prevê prazo de 90 dias para as medidas provisórias.", "C": "O total máximo é de 60 + 60 dias, sem contar o recesso.", "D": "Não existe prazo de 180 dias para a conversão.", "E": "Correto. É a regra do art. 62, §§ 3º e 7º."}, "tags": ["medidas-provisorias", "processo-legislativo", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["medidas-provisorias", "processo-legislativo"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-i-01", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Princípios fundamentais", "subtopic": "Estado Democrático de Direito", "difficulty": "iniciante", "type": "true-false", "statement": "A República Federativa do Brasil é formada pela união indissolúvel dos Estados e Municípios e do Distrito Federal e constitui-se em Estado Democrático de Direito.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "É a redação do art. 1º, caput, da Constituição. A indissolubilidade impede a secessão de qualquer ente.", "alternativeExplanations": {"V": "Correto. É o texto do art. 1º da Constituição.", "F": "Incorreto. É o texto do art. 1º da Constituição."}, "tags": ["principios-fundamentais", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["principios-fundamentais"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-i-02", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Princípios fundamentais", "subtopic": "Soberania popular", "difficulty": "iniciante", "type": "true-false", "statement": "Pela Constituição, todo o poder emana do povo, que o exerce apenas por meio de representantes eleitos.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O parágrafo único do art. 1º diz que o povo exerce o poder por meio de representantes eleitos ou diretamente, nos termos da Constituição, por exemplo por plebiscito, referendo e iniciativa popular.", "alternativeExplanations": {"V": "Incorreto. O povo também exerce o poder diretamente.", "F": "Correto. O povo também exerce o poder diretamente."}, "tags": ["principios-fundamentais", "soberania-popular", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["principios-fundamentais", "soberania-popular"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-i-03", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Gratuidade", "difficulty": "iniciante", "type": "true-false", "statement": "As ações de habeas corpus e de habeas data são gratuitas.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O art. 5º, LXXVII, garante a gratuidade das ações de habeas corpus e habeas data e, na forma da lei, dos atos necessários ao exercício da cidadania.", "alternativeExplanations": {"V": "Correto. A gratuidade está no art. 5º, LXXVII.", "F": "Incorreto. A gratuidade está no art. 5º, LXXVII."}, "tags": ["remedios-constitucionais", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["remedios-constitucionais"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-i-04", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos sociais", "subtopic": "Rol do art. 6º", "difficulty": "iniciante", "type": "true-false", "statement": "A educação, a saúde, a alimentação e a moradia estão entre os direitos sociais previstos no art. 6º da Constituição.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O art. 6º inclui, entre outros, educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança e previdência social.", "alternativeExplanations": {"V": "Correto. Todos esses direitos estão no art. 6º.", "F": "Incorreto. Todos esses direitos estão no art. 6º."}, "tags": ["direitos-sociais", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-sociais"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-i-05", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Penas proibidas", "difficulty": "iniciante", "type": "true-false", "statement": "A Constituição admite a pena de morte para crimes hediondos.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O art. 5º, XLVII, proíbe a pena de morte, salvo em caso de guerra declarada. Também são proibidas as penas de caráter perpétuo, de trabalhos forçados, de banimento e cruéis.", "alternativeExplanations": {"V": "Incorreto. A única exceção é a guerra declarada.", "F": "Correto. A única exceção é a guerra declarada."}, "tags": ["direitos-individuais", "penas", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-individuais", "penas"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-i-06", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos políticos", "subtopic": "Alistamento e voto", "difficulty": "iniciante", "type": "true-false", "statement": "O voto é obrigatório para os maiores de 70 anos.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "Para os maiores de 70 anos, o alistamento e o voto são facultativos (art. 14, § 1º, II, b).", "alternativeExplanations": {"V": "Incorreto. Aos 70 anos, o voto se torna facultativo.", "F": "Correto. Aos 70 anos, o voto se torna facultativo."}, "tags": ["direitos-politicos", "voto", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-politicos", "voto"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-i-07", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Liberdade de expressão", "difficulty": "iniciante", "type": "true-false", "statement": "É livre a manifestação do pensamento, sendo vedado o anonimato.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "É a redação do art. 5º, IV. A vedação do anonimato permite responsabilizar quem abusa da liberdade de expressão.", "alternativeExplanations": {"V": "Correto. É o texto do art. 5º, IV.", "F": "Incorreto. É o texto do art. 5º, IV."}, "tags": ["direitos-individuais", "liberdade-de-expressao", "concursos", "iniciante"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-individuais", "liberdade-de-expressao"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-m-01", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Inviolabilidade do domicílio", "difficulty": "medio", "type": "true-false", "statement": "A casa é asilo inviolável do indivíduo, mas é permitido entrar à noite, sem consentimento do morador, para cumprir ordem judicial.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "A ordem judicial só autoriza a entrada durante o dia. À noite, sem consentimento, só se entra em caso de flagrante delito, desastre ou para prestar socorro.", "alternativeExplanations": {"V": "Incorreto. A ordem judicial só vale durante o dia.", "F": "Correto. A ordem judicial só vale durante o dia."}, "tags": ["direitos-individuais", "domicilio", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-individuais", "domicilio"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-m-02", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Mandado de segurança", "difficulty": "medio", "type": "true-false", "statement": "O mandado de segurança protege direito líquido e certo que não seja amparado por habeas corpus ou habeas data.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "É a redação do art. 5º, LXIX. Por isso se diz que o mandado de segurança tem caráter residual.", "alternativeExplanations": {"V": "Correto. É o texto do art. 5º, LXIX.", "F": "Incorreto. É o texto do art. 5º, LXIX."}, "tags": ["remedios-constitucionais", "mandado-de-seguranca", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["remedios-constitucionais", "mandado-de-seguranca"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-m-03", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Organização do Estado", "subtopic": "Territórios Federais", "difficulty": "medio", "type": "true-false", "statement": "Os Territórios Federais integram a União.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O art. 18, § 2º, diz que os Territórios Federais integram a União. Hoje não há Territórios no Brasil, mas eles podem ser criados por lei complementar.", "alternativeExplanations": {"V": "Correto. É o que diz o art. 18, § 2º.", "F": "Incorreto. É o que diz o art. 18, § 2º."}, "tags": ["organizacao-do-estado", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["organizacao-do-estado"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-m-04", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos políticos", "subtopic": "Condições de elegibilidade", "difficulty": "medio", "type": "true-false", "statement": "Para concorrer a Governador de Estado, a idade mínima exigida é de 35 anos.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "Para Governador e Vice-Governador, a idade mínima é de 30 anos. A de 35 anos vale para Presidente, Vice-Presidente e Senador.", "alternativeExplanations": {"V": "Incorreto. A idade mínima para Governador é de 30 anos.", "F": "Correto. A idade mínima para Governador é de 30 anos."}, "tags": ["direitos-politicos", "elegibilidade", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-politicos", "elegibilidade"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-m-05", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Administração pública", "subtopic": "Cargos em comissão", "difficulty": "medio", "type": "true-false", "statement": "Os cargos em comissão, declarados em lei de livre nomeação e exoneração, dispensam a aprovação prévia em concurso público.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O art. 37, II, ressalva do concurso as nomeações para cargo em comissão. Esses cargos destinam-se apenas a direção, chefia e assessoramento (art. 37, V).", "alternativeExplanations": {"V": "Correto. O art. 37, II, faz essa ressalva.", "F": "Incorreto. O art. 37, II, faz essa ressalva."}, "tags": ["administracao-publica", "cargo-em-comissao", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["administracao-publica", "cargo-em-comissao"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-m-06", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Racismo", "difficulty": "medio", "type": "true-false", "statement": "A prática do racismo constitui crime inafiançável e imprescritível, sujeito à pena de reclusão.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "É a redação do art. 5º, XLII. O racismo é um dos dois crimes imprescritíveis previstos na Constituição.", "alternativeExplanations": {"V": "Correto. É o texto do art. 5º, XLII.", "F": "Incorreto. É o texto do art. 5º, XLII."}, "tags": ["direitos-individuais", "crimes-constitucionais", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-individuais", "crimes-constitucionais"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-m-07", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Nacionalidade", "subtopic": "Cargos privativos de brasileiro nato", "difficulty": "medio", "type": "true-false", "statement": "Brasileiros naturalizados podem ser Ministros de Estado em qualquer pasta, sem exceção.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O cargo de Ministro de Estado da Defesa é privativo de brasileiro nato (art. 12, § 3º, VII). Nas demais pastas, o naturalizado pode ser nomeado.", "alternativeExplanations": {"V": "Incorreto. O Ministro da Defesa precisa ser brasileiro nato.", "F": "Correto. O Ministro da Defesa precisa ser brasileiro nato."}, "tags": ["nacionalidade", "concursos", "medio"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["nacionalidade"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-a-01", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Processo legislativo", "subtopic": "Cláusulas pétreas", "difficulty": "avancado", "type": "true-false", "statement": "Não será objeto de deliberação a proposta de emenda tendente a abolir a forma federativa de Estado.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "A forma federativa de Estado é cláusula pétrea (art. 60, § 4º, I). A proposta tendente a aboli-la não pode sequer ser deliberada.", "alternativeExplanations": {"V": "Correto. A forma federativa é cláusula pétrea.", "F": "Incorreto. A forma federativa é cláusula pétrea."}, "tags": ["clausulas-petreas", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["clausulas-petreas"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-a-02", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Processo legislativo", "subtopic": "Limitações circunstanciais", "difficulty": "avancado", "type": "true-false", "statement": "A Constituição pode ser emendada durante a vigência de intervenção federal, de estado de defesa ou de estado de sítio.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O art. 60, § 1º, proíbe emendar a Constituição durante intervenção federal, estado de defesa ou estado de sítio. São as chamadas limitações circunstanciais.", "alternativeExplanations": {"V": "Incorreto. Nessas situações a Constituição não pode ser emendada.", "F": "Correto. Nessas situações a Constituição não pode ser emendada."}, "tags": ["emenda-constitucional", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["emenda-constitucional"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-a-03", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Processo legislativo", "subtopic": "Medidas provisórias", "difficulty": "avancado", "type": "true-false", "statement": "O Presidente da República pode editar medida provisória sobre direito penal, desde que haja relevância e urgência.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O art. 62, § 1º, I, b, proíbe medidas provisórias sobre direito penal, processual penal e processual civil, mesmo com relevância e urgência.", "alternativeExplanations": {"V": "Incorreto. Direito penal é matéria vedada às medidas provisórias.", "F": "Correto. Direito penal é matéria vedada às medidas provisórias."}, "tags": ["medidas-provisorias", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["medidas-provisorias"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-a-04", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Cláusula de abertura", "difficulty": "avancado", "type": "true-false", "statement": "Os direitos e garantias expressos na Constituição não excluem outros decorrentes do regime e dos princípios por ela adotados ou dos tratados internacionais de que o Brasil seja parte.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "É a redação do art. 5º, § 2º, conhecida como cláusula de abertura: o rol de direitos fundamentais não é taxativo.", "alternativeExplanations": {"V": "Correto. É o texto do art. 5º, § 2º.", "F": "Incorreto. É o texto do art. 5º, § 2º."}, "tags": ["direitos-fundamentais", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-fundamentais"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-a-05", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Direitos e garantias fundamentais", "subtopic": "Tratados de direitos humanos", "difficulty": "avancado", "type": "true-false", "statement": "Tratados e convenções internacionais sobre direitos humanos aprovados, em cada Casa do Congresso, em dois turnos, por três quintos dos votos dos membros equivalem às emendas constitucionais.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "É o que prevê o art. 5º, § 3º, incluído pela Emenda Constitucional 45/2004. Um exemplo é a Convenção sobre os Direitos das Pessoas com Deficiência.", "alternativeExplanations": {"V": "Correto. É o texto do art. 5º, § 3º.", "F": "Incorreto. É o texto do art. 5º, § 3º."}, "tags": ["direitos-fundamentais", "tratados", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["direitos-fundamentais", "tratados"], "origin": "nabulab"},
  {"id": "direito-constitucional-conc-v1-vf-a-06", "area": "Concursos Públicos", "subject": "direito-constitucional", "subjectName": "Direito Constitucional", "topic": "Processo legislativo", "subtopic": "Emenda constitucional", "difficulty": "avancado", "type": "true-false", "statement": "A matéria de proposta de emenda rejeitada ou havida por prejudicada pode ser objeto de nova proposta na mesma sessão legislativa.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O art. 60, § 5º, proíbe que a matéria de PEC rejeitada ou prejudicada seja objeto de nova proposta na mesma sessão legislativa.", "alternativeExplanations": {"V": "Incorreto. Só pode ser reapresentada na sessão legislativa seguinte.", "F": "Correto. Só pode ser reapresentada na sessão legislativa seguinte."}, "tags": ["emenda-constitucional", "concursos", "avancado"], "examTags": ["concursos"], "educationLevel": "ensino-medio", "skills": ["emenda-constitucional"], "origin": "nabulab"},
];
